"""Character-specific moves and facing-relative arcade command recognition."""
from .settings import ATTACKS, MOVES, COMMANDS

def move_spec(name, action):
    return {'kind': 'projectile' if action in ('blast', 'super') else 'melee',
            **ATTACKS[action], **MOVES.get(name, {}).get(action, {})}

class CommandBuffer:
    def __init__(self):
        self.history = [[], []]

    def clear(self):
        self.history = [[], []]

    def push(self, player, action, facing, now, finishing=False):
        token = ('down' if action == 'duck' else
                 ('forward' if (action == 'right') == (facing > 0) else 'back')
                 if action in ('left', 'right') else action)
        if token not in ('down', 'forward', 'back', 'jab', 'kick', 'blast'):
            return None
        history = [(t, value) for t, value in self.history[player] if now-t <= COMMANDS['window_seconds']]
        history.append((now, token));self.history[player] = history[-6:]
        values = [value for _, value in history]
        for name in (('fatality',) if finishing else ('super', 'signature')):
            command = COMMANDS[name]
            if values[-len(command):] == command:
                self.history[player] = []
                return 'finish' if name == 'fatality' else name
        return None

