"""Frame-independent fighting rules, separate from input, art, audio and configuration."""
from dataclasses import dataclass, field
import math
import random
from .settings import DISPLAY, MATCH, AI, ATTACKS, FIGHTERS
from .moves import move_spec
from .cinematics import impact_times

WIDTH, HEIGHT, FLOOR = DISPLAY['width'], DISPLAY['height'], DISPLAY['floor_y']
PALETTES = FIGHTERS

@dataclass
class Fighter:
    name: str
    x: float
    facing: int
    hp: float = 100
    ghost_hp: float = 100
    meter: float = MATCH['starting_energy']
    z: float = 0
    vz: float = 0
    vx: float = 0
    action: str = 'idle'
    elapsed: float = 0
    stun: float = 0
    dash_cd: float = 0
    invincible: float = 0
    combo: int = 0
    combo_time: float = 0
    flash: float = 0
    guard: float = 100
    guarding: bool = False
    crouching: bool = False
    hit_done: bool = False
    queued: str = ''
    queue_time: float = 0
    walking: float = 0
    wins: int = 0
    jump_buffer: float = 0
    hit_marks: set = field(default_factory=set)

    @property
    def height(self): return 112 if self.crouching else 210
    @property
    def attacking(self): return self.action in ATTACKS
    @property
    def color(self): return PALETTES[self.name]['main']

@dataclass
class Projectile:
    owner: int
    x: float
    z: float
    direction: int
    super: bool = False
    age: float = 0

@dataclass
class Particle:
    x: float
    y: float
    vx: float
    vy: float
    life: float
    maxlife: float
    color: str
    size: float
    kind: str = 'spark'

class Combat:
    def __init__(self, seed=None):
        self.rng=random.Random(seed)
        self.state='title'; self.difficulty=1; self.training=False
        self.fighters=[Fighter('VESPER',270,1),Fighter('PYRE',730,-1)]
        self.projectiles=[]; self.particles=[]; self.events=[]
        self.round=1; self.timer=60.; self.phase_time=0.; self.freeze=0.; self.shake=0.
        self.flash=0.; self.slow=0.; self.ai_clock=0.; self.ai_keys=set()
        self.winner=None; self.message=''; self.message_time=0.; self.total_time=0.
        self.training_reset=0.; self.dummy_guard=False
        self.mode='arcade';self.opponent_keys=set();self.finisher_time=0.;self.finisher_demo=False;self.finish_fired=False
        self.finisher_hits=set()

    def start(self, name='VESPER', difficulty=1, training=False, mode='arcade', opponent=None):
        if name not in FIGHTERS:raise ValueError('Unknown player fighter: '+name)
        if opponent is None:opponent='PYRE' if name=='VESPER' else 'VESPER'
        if opponent not in FIGHTERS:raise ValueError('Unknown opponent fighter: '+opponent)
        self.difficulty=difficulty; self.training=training;self.mode='training' if training else mode
        self.finisher_time=0.;self.finisher_demo=False;self.finish_fired=False
        self.fighters=[Fighter(name,300,1),Fighter(opponent,WIDTH-300,-1)]
        self.round=1; self.projectiles=[]; self.particles=[]; self.events=[]
        self.winner=None; self.freeze=0; self.shake=0; self.flash=0
        self.reset_round()

    def reset_round(self):
        for i,f in enumerate(self.fighters):
            wins=f.wins; name=f.name
            self.fighters[i]=Fighter(name,300 if i==0 else WIDTH-300,1 if i==0 else -1,wins=wins)
        if self.training:
            self.fighters[0].meter=100
            self.fighters[0].x=WIDTH/2-70;self.fighters[1].x=WIDTH/2+70
        self.timer=MATCH['round_seconds']; self.state='intro'; self.phase_time=MATCH['intro_seconds']
        self.projectiles=[]; self.ai_clock=0; self.ai_keys=set(); self.training_reset=0
        self.message=''; self.message_time=0; self.events.append('round')

    def pop_events(self):
        ev,self.events=self.events,[]
        return ev

    def burst(self,x,y,color,count=18,power=1):
        for _ in range(count):
            a=self.rng.uniform(0,math.tau); speed=self.rng.uniform(90,430)*power
            life=self.rng.uniform(.18,.48)
            self.particles.append(Particle(x,y,math.cos(a)*speed,math.sin(a)*speed,life,life,
                                           self.rng.choice([color,color,'#ffffff','#fff2a0']),self.rng.uniform(1.5,4)))
        self.particles=self.particles[-240:]

    def attack(self,i,kind):
        if self.state!='fight' or kind not in ATTACKS:return False
        f=self.fighters[i]; spec=move_spec(f.name,kind)
        if f.hp<=0 or f.stun>0:return False
        if spec.get('ground_only') and f.z>0:return False
        if f.attacking or f.action=='dash':
            f.queued=kind; f.queue_time=.18
            return False
        if f.meter+1e-6<spec['cost']:
            if i==0:self.message='NEED '+str(spec['cost'])+' ENERGY';self.message_time=.65
            return False
        f.meter=max(0,f.meter-spec['cost']);f.action=kind;f.elapsed=0;f.hit_done=False
        f.hit_marks.clear()
        f.guarding=False;f.crouching=False
        f.facing=1 if self.fighters[1-i].x>=f.x else -1
        f.invincible=max(f.invincible,spec.get('invincible',0))
        if spec.get('lift') and f.z<=0:f.z=1;f.vz=spec['lift']
        if spec['kind']=='teleport':
            self.burst(f.x,FLOOR-100,f.color,22)
            f.x=max(47,min(WIDTH-47,self.fighters[1-i].x-f.facing*92))
        if kind=='super':
            self.freeze=.09;self.flash=.16;self.shake=6
            self.message=PALETTES[f.name]['special'];self.message_time=.6;self.events.append('super')
        else:
            self.events.append('swing' if kind in ('jab','kick') else 'charge')
            if kind in ('blast','signature'):
                self.message=spec.get('label',kind.upper());self.message_time=.55
        return True

    def dash(self,i,direction=0):
        f=self.fighters[i]
        if self.state!='fight' or f.stun>0 or f.attacking or f.dash_cd>0 or f.z>0:return
        f.action='dash';f.elapsed=0;f.dash_cd=.7;f.invincible=.12
        f.vx=(direction or f.facing)*670;self.events.append('dash')

    def hit(self,owner,damage,stun,push,x,z,is_super=False,meter_gain=True,unblockable=False,launch=0):
        a=self.fighters[owner];b=self.fighters[1-owner]
        if b.hp<=0 or b.invincible>0:return False
        blocked=not unblockable and b.guarding and b.z<=0 and b.stun<=0 and b.facing*(a.x-b.x)>0
        if blocked:
            b.guard-=40 if is_super else 17
            if b.guard<=0:
                b.guard=30;b.guarding=False;b.stun=.85
                self.message='GUARD BREAK';self.message_time=.8;self.events.append('break')
                blocked=False
            else:
                b.hp=max(.1,b.hp-damage*.07);b.vx=a.facing*push*.4
                b.flash=.1;self.freeze=.025;self.shake=2
                self.burst(x,FLOOR-z,'#a7d9ff',11,.6);self.events.append('block')
                a.meter=min(100,a.meter+(4 if meter_gain else 0));b.meter=min(100,b.meter+3)
                return True
        b.hp=max(0,b.hp-damage);b.stun=max(b.stun,stun)
        b.action='hurt';b.elapsed=0;b.vx=a.facing*push;b.flash=.15
        if is_super or launch:b.vz=launch or 360;b.z=max(1,b.z)
        a.combo=a.combo+1 if a.combo_time>0 else 1;a.combo_time=1.15
        a.meter=min(100,a.meter+(11 if meter_gain and not is_super else 0));b.meter=min(100,b.meter+8)
        self.burst(x,FLOOR-z,a.color,45 if is_super else 22,1.5 if is_super else 1)
        self.freeze=.10 if is_super else .046;self.shake=15 if is_super else 6
        self.events.append('impact_super' if is_super else 'hit')
        if b.hp<=0:
            b.action='ko';self.finish_round(owner)
        return True

    def finish_round(self,winner):
        if self.state!='fight':return
        if self.training:
            self.state='training_reset';self.phase_time=1.8;return
        self.winner=winner
        if winner is not None:self.fighters[winner].wins+=1
        self.state='round_end';self.phase_time=MATCH['round_break_seconds']
        self.message='DOUBLE K.O.' if winner is None else 'K.O.'
        self.message_time=2.5;self.shake=13;self.events.append('ko')

    def decide_ai(self,dt):
        if self.mode=='versus':return self.opponent_keys
        if self.training:return {'guard'} if self.dummy_guard else set()
        self.ai_clock-=dt
        if self.ai_clock>0:return self.ai_keys
        level=self.difficulty;settings=AI['levels'][level]
        self.ai_clock=settings['reaction']+self.rng.uniform(0,.09)
        a,b=self.fighters[1],self.fighters[0];d=abs(a.x-b.x)
        toward='right' if b.x>a.x else 'left';away='left' if toward=='right' else 'right'
        k=set();incoming=any(p.owner==0 and abs(p.x-a.x)<250 for p in self.projectiles)
        if (b.attacking and d<160 or incoming) and self.rng.random()<settings['block_chance']:
            k.add('guard')
            if incoming and self.rng.random()<.32:k={'jump',toward}
        elif d>110:
            k.add(toward)
            if d>280 and a.meter>=25 and move_spec(a.name,'blast')['kind']=='projectile' and self.rng.random()<.35:self.attack(1,'blast')
            if d<210 and a.meter>=35 and self.rng.random()<.26:self.attack(1,'signature')
            if d<180 and a.meter>=100 and self.rng.random()<.5:self.attack(1,'super')
            if d>260 and self.rng.random()<.06+level*.02:self.dash(1,1 if b.x>a.x else -1)
            if self.rng.random()<.025:k.add('jump')
        else:
            if self.rng.random()<.14:k.add(away)
            elif self.rng.random()<.10:k.add('duck')
            elif self.rng.random()<settings['attack_chance']:
                if a.meter>=100 and self.rng.random()<.5:self.attack(1,'super')
                elif a.meter>=35 and self.rng.random()<.30:self.attack(1,'signature')
                elif a.meter>=25 and self.rng.random()<.25:self.attack(1,'blast')
                else:self.attack(1,'kick' if self.rng.random()<.40 else 'jab')
        self.ai_keys=k
        return k

    def update_fighter(self,i,keys,dt):
        f=self.fighters[i];o=self.fighters[1-i]
        for attr in ('stun','dash_cd','invincible','combo_time','flash','queue_time','jump_buffer'):
            setattr(f,attr,max(0,getattr(f,attr)-dt))
        if f.combo_time<=0:f.combo=0
        f.ghost_hp=max(f.hp,f.ghost_hp-dt*27)
        f.meter=min(100,f.meter+dt*(MATCH['training_energy_regen'] if self.training and i==0 else MATCH['energy_regen']))
        f.guard=min(100,f.guard+dt*(8 if f.guarding else 22))
        f.elapsed+=dt
        f.guarding=False;f.crouching=False;f.walking=0
        if f.hp>0 and f.stun<=0 and not f.attacking and f.action!='dash':
            f.facing=1 if o.x>=f.x else -1
            f.guarding='guard' in keys and f.z<=0
            f.crouching='duck' in keys and f.z<=0 and not f.guarding
            direction=int('right' in keys)-int('left' in keys)
            if ('jump' in keys or f.jump_buffer>0) and f.z<=0 and not f.guarding:
                f.jump_buffer=0
                f.vz=MATCH['jump_speed'];f.z=1;self.events.append('jump')
            if not f.guarding and not f.crouching:
                speed=PALETTES[f.name]['speed'];f.x+=direction*speed*dt;f.walking=direction
            f.action='guard' if f.guarding else 'duck' if f.crouching else 'walk' if direction else 'idle'
            if f.queued and f.queue_time>0:
                q=f.queued;f.queued='';self.attack(i,q)
        if f.action=='dash':
            if f.elapsed>.15:f.action='idle';f.vx=0
            if int(f.elapsed*60)%3==0:
                self.particles.append(Particle(f.x,FLOOR-f.z-65,0,0,.18,.18,f.color,30,'echo'))
        if f.stun>0 or f.hp<=0 or f.action=='dash':f.x+=f.vx*dt
        f.vx*=math.exp(-dt*(3 if f.action=='dash' else 9))
        if f.z>0 or f.vz>0:
            f.z+=f.vz*dt;f.vz-=MATCH['gravity']*dt
            if f.z<=0:
                f.z=0;f.vz=0
                self.burst(f.x,FLOOR,'#7b99b6',5,.22)
        f.x=max(47,min(WIDTH-47,f.x))
        if f.attacking:
            spec=move_spec(f.name,f.action)
            if spec.get('travel') and f.elapsed<spec['start']+spec['active']:
                distance=(o.x-f.x)*f.facing
                f.x+=f.facing*min(spec['travel']*dt,max(0,distance-spec.get('stop_gap',80)))
                f.x=max(47,min(WIDTH-47,f.x))
            if not f.hit_done and spec['start']<=f.elapsed<=spec['start']+spec['active']:
                if spec['kind']=='projectile':
                    self.projectiles.append(Projectile(i,f.x+f.facing*66,f.z+spec['level'],f.facing,f.action=='super'))
                    f.hit_done=True;self.events.append('blast')
                else:
                    attack_z=f.z+spec['level'];dx=(o.x-f.x)*f.facing
                    in_range=0<=dx<=spec['reach']+23 and o.z-9<=attack_z<=o.z+o.height+9
                    if spec.get('ground_only'):in_range=in_range and o.z<=25
                    if spec['kind']=='flurry':
                        for mark,timing in enumerate(spec['hits']):
                            if mark not in f.hit_marks and timing<=f.elapsed:
                                f.hit_marks.add(mark)
                                last=mark==len(spec['hits'])-1
                                if in_range:
                                    self.hit(i,spec['damage']*PALETTES[f.name]['power'],spec['stun'],
                                             spec.get('last_push',350) if last else spec['push'],(f.x+o.x)/2,attack_z,
                                             last and f.action=='super',meter_gain=f.action!='super',
                                             launch=spec.get('last_launch',0) if last else 0)
                                    if self.state!='fight':break
                    elif in_range:
                        f.hit_done=self.hit(i,spec['damage']*PALETTES[f.name]['power'],spec['stun'],spec['push'],
                                           (f.x+o.x)/2,attack_z,f.action=='super',meter_gain=f.action!='super',
                                           unblockable=spec['kind']=='grapple',launch=spec.get('launch',0))
            if f.elapsed>=spec['duration']:f.action='idle'

    def update(self,dt,player_keys=None):
        dt=min(dt,.04);self.total_time+=dt
        self.shake=max(0,self.shake-dt*35);self.flash=max(0,self.flash-dt)
        self.message_time=max(0,self.message_time-dt)
        for p in self.particles:
            p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=360*dt
        self.particles=[p for p in self.particles if p.life>0]
        if self.state in ('title','options','moves','paused','match_end'):return
        if self.state=='finish_window':
            self.phase_time-=dt
            if self.mode!='versus' and self.winner==1 and self.phase_time<MATCH['finisher_window_seconds']-1.1:
                self.start_finisher(1)
            elif self.phase_time<=0:self.state='match_end';self.events.append('win')
            return
        if self.state=='finisher':
            self.finisher_time+=dt
            times=impact_times(self.fighters[self.winner].name)
            for mark,timing in enumerate(times):
                if self.finisher_time>=timing and mark not in self.finisher_hits:
                    self.finisher_hits.add(mark);last=mark==len(times)-1
                    self.events.append('finish' if last else 'hit');self.shake=24 if last else 8;self.flash=.25 if last else .07
                    loser=self.fighters[1-self.winner]
                    self.burst(loser.x,FLOOR-110,self.fighters[self.winner].color,140 if last else 30,2.3 if last else 1)
                    if last:self.finish_fired=True;loser.action='ko'
            if self.finisher_time>=MATCH['finisher_seconds']:
                if self.finisher_demo:self.reset_round();self.state='fight'
                else:self.state='match_end';self.events.append('win')
            return
        if self.freeze>0:self.freeze=max(0,self.freeze-dt);return
        if self.state!='fight':
            self.phase_time-=dt
            if self.state in ('round_end','training_reset'):
                for f in self.fighters:
                    f.elapsed+=dt;f.z=max(0,f.z+f.vz*dt);f.vz-=MATCH['gravity']*dt
                    f.x=max(50,min(WIDTH-50,f.x+f.vx*dt));f.vx*=.88
            if self.phase_time<=0:
                if self.state=='intro':self.state='fight';self.message='FIGHT';self.message_time=.65
                elif self.state=='training_reset':
                    self.reset_round();self.state='fight'
                elif max(f.wins for f in self.fighters)>=MATCH['wins_required']:
                    self.state='finish_window';self.phase_time=MATCH['finisher_window_seconds'];self.message='';self.message_time=0
                else:self.round+=1;self.reset_round()
            return
        ai=self.decide_ai(dt)
        self.update_fighter(0,player_keys or set(),dt)
        self.update_fighter(1,ai,dt)
        a,b=self.fighters
        if abs(a.x-b.x)<46 and abs(a.z-b.z)<90:
            overlap=(46-abs(a.x-b.x))/2;direction=1 if a.x<=b.x else -1
            a.x=max(47,min(WIDTH-47,a.x-overlap*direction));b.x=max(47,min(WIDTH-47,b.x+overlap*direction))
        for p in list(self.projectiles):
            p.age+=dt;p.x+=p.direction*(510 if p.super else 630)*dt
            target=self.fighters[1-p.owner];radius=39 if p.super else 19
            if abs(p.x-target.x)<radius+24 and target.z-radius<p.z<target.z+target.height+radius:
                spec=move_spec(self.fighters[p.owner].name,'super' if p.super else 'blast')
                if self.hit(p.owner,spec['damage'],spec['stun'],spec['push'],p.x,p.z,p.super):
                    if p in self.projectiles:self.projectiles.remove(p)
            elif p.x<-100 or p.x>WIDTH+100 or p.age>3:
                if p in self.projectiles:self.projectiles.remove(p)
        for p in list(self.projectiles):
            for q in list(self.projectiles):
                if p.owner!=q.owner and abs(p.x-q.x)<30 and abs(p.z-q.z)<40:
                    self.burst((p.x+q.x)/2,FLOOR-p.z,'#e7baff',26)
                    if p in self.projectiles:self.projectiles.remove(p)
                    if q in self.projectiles:self.projectiles.remove(q)
        if not self.training:
            self.timer=max(0,self.timer-dt)
            if self.timer<=0:self.finish_round(0 if a.hp>b.hp else 1 if b.hp>a.hp else None)
        elif b.hp<100 and not a.attacking and a.combo_time<=0:
            b.hp=min(100,b.hp+dt*12)

    def start_finisher(self, winner=0, demo=False):
        if demo and self.training and self.state=='fight':
            self.finisher_demo=True
        elif self.state!='finish_window' or winner!=self.winner:
            return False
        self.winner=winner;self.state='finisher';self.finisher_time=0;self.finish_fired=False
        self.finisher_hits=set()
        self.projectiles=[];self.particles=[];self.freeze=0;self.events.append('super')
        a,b=self.fighters[winner],self.fighters[1-winner]
        a.x=WIDTH*.34 if winner==0 else WIDTH*.66;b.x=WIDTH*.66 if winner==0 else WIDTH*.34
        a.facing=1 if a.x<b.x else -1;b.facing=-a.facing
        a.z=b.z=0;a.action='super';a.elapsed=.25;b.action='hurt';b.elapsed=0
        return True

