"""Distinct, timed finishing sequences; combat owns the match outcome."""
import math
from .settings import FIGHTERS, DISPLAY, THEME, GRAPHICS, FINISHERS

def impact_times(name):
    return FINISHERS[FIGHTERS[name]['fatality_style']]['impacts']

def draw_finisher(r,e):
    t=e.finisher_time;a=e.fighters[e.winner];b=e.fighters[1-e.winner]
    w=DISPLAY['width'];h=DISPLAY['height'];floor=DISPLAY['floor_y']
    style=FIGHTERS[a.name]['fatality_style'];col=a.color;light=FIGHTERS[a.name]['light'];d=a.facing
    ax=a.x;bx=b.x;ay=by=floor;ap='cast';bp='hurt'
    r.tag='world'
    if style in ('dragon','atlas'):
        approach=min(1,t/.62)
        ax=a.x+(b.x-d*(105 if style=='dragon' else 130)-a.x)*approach
        if t<.62:ap='walk'
        elif style=='dragon':
            ap=('jab' if int((t-.62)*11)%2==0 else 'guard') if t<1.55 else 'cast' if t<2.5 else 'idle'
            if .65<t<1.55:
                for j in range(4):
                    yy=floor-160+j*15
                    r.line([(ax-d*(40+j*11),yy),(bx-d*20,yy-5)],col if j==0 else FIGHTERS[a.name]['dark'],3)
            if 1.55<t<2.2:
                radius=8+(t-1.55)*62
                r.oval(ax+d*73,floor-148,radius,radius,'',light,2)
        else:
            ap='cast' if t<1.18 else ('jump' if int(t*9)%2==0 else 'kick') if t<2.2 else 'kick' if t<2.55 else 'idle'
            if 1.18<t<2.2:
                ay=floor-math.sin((t-1.18)/1.02*math.pi)*65
                for j in range(4):
                    phase=t*9+j*.4
                    r.line([(ax+math.cos(phase)*100,ay-100+math.sin(phase)*72),
                            (ax+math.cos(phase+.6)*140,ay-100+math.sin(phase+.6)*92)],col,3)
    elif style=='roundhouse':
        ax=a.x+(b.x-d*135-a.x)*min(1,t/.6)
