"""Configuration is split by concern; restart the game after editing JSON files."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parent.parent

def read(name):
    path = ROOT / 'config' / (name + '.json')
    try:
        return json.loads(path.read_text())
    except (OSError, ValueError) as error:
        raise ValueError(f'Cannot load {path.name}: {error}') from error

DISPLAY = read('display')
GRAPHICS = read('graphics')
AUDIO = read('audio')
MATCH = read('match')
AI = read('ai')
THEME = read('theme')
ARENA = read('arena')
CONTROLS = read('controls')
ATTACKS = read('attacks')
ROSTER = read('roster')
COMMANDS = read('commands')
FINISHERS = read('finishers')
FIGHTERS = {name: read('fighters/' + name.lower()) for name in ROSTER['fighters']}
MOVES = {name: read(fighter['move_file']) for name, fighter in FIGHTERS.items()}
if DISPLAY['width'] < 960 or DISPLAY['height'] < 600:
    raise ValueError('Display needs at least 960 × 600 pixels for the interface.')
if MATCH['round_seconds'] <= 0 or MATCH['wins_required'] < 1:
    raise ValueError('Round time and wins required must be positive.')
for name, attack in ATTACKS.items():
    if not 0 < attack['start'] < attack['start'] + attack['active'] <= attack['duration']:
        raise ValueError(f'Invalid timing for attack {name}.')
for fighter, overrides in MOVES.items():
    for name, values in overrides.items():
        attack = {**ATTACKS[name], **values}
        if not 0 < attack['start'] < attack['start'] + attack['active'] <= attack['duration']:
            raise ValueError(f'Invalid timing for {fighter}: {name}.')
        if any(not attack['start'] <= hit <= attack['start'] + attack['active'] for hit in attack.get('hits', [])):
            raise ValueError(f'Invalid multi-hit timing for {fighter}: {name}.')

for name, fighter in FIGHTERS.items():
    timings = FINISHERS[fighter['fatality_style']]['impacts']
    if not timings or timings != sorted(set(timings)) or not 0 < timings[0] <= timings[-1] < MATCH['finisher_seconds']:
        raise ValueError(f'Invalid fatality timing for {name}.')

