"""Application lifecycle and configurable keyboard input."""
import time
import tkinter as tk
from .settings import DISPLAY, MATCH, CONTROLS, ROSTER
from .moves import CommandBuffer
from .combat import Combat
from .art import Art
from .audio import Audio
from .render import Renderer

class Game:
    def __init__(self):
        self.root=tk.Tk();self.root.title(DISPLAY['title'])
        self.root.geometry(f"{DISPLAY['width']}x{DISPLAY['height']}+25+38")
        self.root.resizable(False,False);self.root.configure(bg='#08070a')
        self.fullscreen=DISPLAY['fullscreen'];self.root.attributes('-fullscreen',self.fullscreen)
        self.canvas=tk.Canvas(self.root,width=DISPLAY['width'],height=DISPLAY['height'],bg='#08070a',highlightthickness=0)
        self.canvas.pack(expand=True)
        self.engine=Combat();self.audio=Audio();self.art=Art();self.selected=ROSTER['default_player']
        self.opponent=ROSTER['default_opponent'];self.selection_slot=0;self.commands=CommandBuffer();self.moves_resume='title'
        self.difficulty=MATCH['default_difficulty'];self.keys=set();self.mouse=(-1,-1)
        self.renderer=Renderer(self.canvas,self.art,self);self.running=True;self.resume_state='fight'
        self.last=time.perf_counter();self.frame_times=[]
        self.root.bind('<KeyPress>',self.key_down);self.root.bind('<KeyRelease>',self.key_up)
        self.root.bind('<FocusOut>',self.focus_out)
        self.canvas.bind('<Motion>',lambda event:setattr(self,'mouse',(event.x,event.y)))
        self.canvas.bind('<Button-1>',self.click)
        self.root.protocol('WM_DELETE_WINDOW',self.close)
        self.canvas.focus_set();self.root.after(30,self.loop)
    def start(self,mode='arcade'):
        self.keys.clear();self.commands.clear();self.engine.start(self.selected,self.difficulty,mode=='training',mode,opponent=self.opponent)
        self.audio.started=True
    def choose(self,name):
        if self.selection_slot==0:self.selected=name
        else:self.opponent=name
    def cycle(self,direction,slot=None):
        slot=self.selection_slot if slot is None else slot;names=ROSTER['fighters']
        current=self.selected if slot==0 else self.opponent
        name=names[(names.index(current)+direction)%len(names)]
        if slot==0:self.selected=name
        else:self.opponent=name
    def toggle_moves(self):
        if self.engine.state=='moves':self.engine.state=self.moves_resume
        else:self.moves_resume=self.engine.state;self.engine.state='moves'
        self.keys.clear();self.commands.clear()
    def to_title(self):
        self.engine.state='title';self.keys.clear();self.commands.clear();self.audio.started=False;self.audio.stop()
    def resume(self):self.keys.clear();self.engine.state=self.resume_state
    def close(self):self.running=False;self.audio.stop();self.root.destroy()
    def fullscreen_toggle(self):
        self.fullscreen=not self.fullscreen;self.root.attributes('-fullscreen',self.fullscreen)
    def focus_out(self,event):
        self.keys.clear()
        if self.running:self.root.after(70,self.pause_if_unfocused)
    def pause_if_unfocused(self):
        if self.running and self.root.focus_displayof() is None and self.engine.state in ('fight','intro','finish_window'):
            self.resume_state=self.engine.state;self.engine.state='paused'
    def click(self,event):
        self.canvas.focus_set()
        for x,y,w,h,action in list(self.renderer.buttons):
            if x<=event.x<=x+w and y<=event.y<=y+h:action();break
    def key_up(self,event):self.keys.discard(event.keysym.lower())
    def key_down(self,event):
        key=event.keysym.lower();fresh=key not in self.keys;self.keys.add(key)
        if not fresh:return
        e=self.engine;state=e.state;global_action=CONTROLS['global'].get(key)
        if global_action=='mute':self.audio.toggle();return
        if global_action=='fullscreen':self.fullscreen_toggle();return
        if global_action=='moves':self.toggle_moves();return
        if state=='moves':
            if key=='escape':self.toggle_moves()
            return
        if state=='options':
            if key in ('escape','g'):e.state='title'
            return
        if state=='title':
            if key in ('return','kp_enter'):self.start('arcade')
            elif key=='t':self.start('training')
            elif key=='v':self.start('versus')
            elif key=='g':e.state='options'
            elif key in ('1','2','3'):self.difficulty=int(key)-1
            elif key=='tab':self.selection_slot=1-self.selection_slot
            elif key in ('a','d'):self.cycle(-1 if key=='a' else 1)
            elif key in ('left','right'):self.cycle(-1 if key=='left' else 1,slot=1)
            return
        if global_action=='pause':
            if state=='paused':self.resume()
            elif state=='match_end':self.to_title()
            else:self.resume_state=state;e.state='paused';self.keys.clear()
            return
        if state=='paused':
            if key=='return':self.resume()
            elif key=='q':self.to_title()
            return
        if state=='match_end':
            if key in ('return','r'):self.start(e.mode)
            return
        if global_action=='restart':self.start(e.mode);return
        if e.training and CONTROLS['training'].get(key)=='dummy_guard':e.dummy_guard=not e.dummy_guard
        for i,section in enumerate(('player_one','player_two')):
            if i==1 and e.mode!='versus':continue
            mapping=CONTROLS[section];action=mapping.get(key)
            command=self.commands.push(i,action,e.fighters[i].facing,time.perf_counter(),finishing=state=='finish_window')
            action=command or action
            if action in ('jab','kick','blast','signature','super'):e.attack(i,action)
            elif action=='jump':e.fighters[i].jump_buffer=.14
            elif action=='dash':
                held=self.held(section);e.dash(i,int('right' in held)-int('left' in held))
            elif action=='finish':e.start_finisher(i,demo=e.training)
    def held(self,section):
        mapping=CONTROLS[section]
        return {mapping[k] for k in self.keys if k in mapping}
    def loop(self):
        if not self.running:return
        now=time.perf_counter();dt=min(.04,now-self.last);self.last=now
        self.engine.opponent_keys=self.held('player_two')
        self.engine.update(dt,self.held('player_one'))
        self.audio.tick()
        for event in self.engine.pop_events():self.audio.play(event)
        self.renderer.render(dt)
        elapsed=time.perf_counter()-now
        self.frame_times.append(elapsed)
        if len(self.frame_times)>120:self.frame_times.pop(0)
        self.root.after(max(1,int(1000/DISPLAY['fps']-elapsed*1000)),self.loop)


def run():Game().root.mainloop()

