"""Load prepared PNG sprite frames. Pillow is needed only to rebuild source art."""
from fractions import Fraction
import json
import tkinter as tk
from .settings import ROOT, FIGHTERS, GRAPHICS, ARENA

class Art:
    def __init__(self):
        self.background=tk.PhotoImage(file=str(ROOT/ARENA['image']))
        self.frames={};self.padding={}
        for name,character in FIGHTERS.items():
            directory=ROOT/character['sprite_folder']
            meta=json.loads((directory/'frames.json').read_text())
            scale=Fraction(GRAPHICS['sprite_height']/meta['nominal_height']).limit_denominator(4)
            for pose,info in meta['frames'].items():
                for facing in ('r','l'):
                    image=tk.PhotoImage(file=str(directory/f'{pose}_{facing}.png'))
                    ratio=1 if pose in ('portrait','thumb') else float(scale)
                    if pose not in ('portrait','thumb') and scale!=1:
                        image=image.zoom(scale.numerator).subsample(scale.denominator)
                    key=(name,pose,facing)
                    self.frames[key]=image;self.padding[key]=info['padding']*ratio

    def frame(self,name,pose,facing):
        key=(name,pose,'r' if facing>0 else 'l')
        return self.frames[key],self.padding[key]

