"""Local audio playback; missing audio devices never prevent gameplay."""
from pathlib import Path
import subprocess
import sys
import time
from .settings import ROOT, AUDIO

class Audio:
    def __init__(self):
        self.enabled=AUDIO['enabled'];self.music=None;self.voices=[];self.last={};self.started=False
        self.player='/usr/bin/afplay' if sys.platform=='darwin' else None
    def play(self,name):
        if not self.enabled or not self.player:return
        name={'impact_super':'super','break':'block','jump':'dash','finish':'finish'}.get(name,name)
        now=time.monotonic()
        if now-self.last.get(name,0)<.075:return
        self.last[name]=now
        self.voices=[p for p in self.voices if p.poll() is None]
        path=ROOT/'assets/audio'/f'{name}.wav'
        if path.exists() and len(self.voices)<AUDIO['max_voices']:
            try:self.voices.append(subprocess.Popen([self.player,'-v',str(AUDIO['effects_volume']),str(path)],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL))
            except OSError:pass
    def tick(self):
        if self.enabled and self.started and self.player and (self.music is None or self.music.poll() is not None):
            try:self.music=subprocess.Popen([self.player,'-v',str(AUDIO['music_volume']),str(ROOT/AUDIO['music_file'])],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
            except OSError:pass
    def toggle(self):
        self.enabled=not self.enabled
        if not self.enabled:self.stop()
    def stop(self):
        for process in self.voices+([self.music] if self.music else []):
            if process.poll() is None:process.terminate()
        self.voices=[];self.music=None

