        else: self.commands.append(command)
    def create_rectangle(self,*args,**kw): self.add('rect',args,kw)
    def create_polygon(self,*args,**kw): self.add('polygon',args,kw)
    def create_line(self,*args,**kw): self.add('line',args,kw)
