    def create_text(self,*args,**kw): self.add('text',args,kw)
    def create_image(self,*args,**kw): self.add('image',args,kw)
    def delete(self,tag): self.commands=[]
    def move(self,tag,x,y):
        for _,_,options in self.commands:
            if tag in options.get('tags',()): options['offset']=(x,y)
    def focus_set(self): pass

class Art:
    def __init__(self):
        self.background=ARENA['image']; self.frames={}
        for name,fighter in FIGHTERS.items():
            folder=fighter['sprite_folder']
