            for pose,info in meta['frames'].items():
                ratio=1 if pose in ('portrait','thumb') else scale
                for facing in ('r','l'):
                    self.frames[name,pose,facing]=({'path':f'{folder}/{pose}_{facing}.png','scale':ratio},info['padding']*ratio)
    def frame(self,name,pose,facing): return self.frames[name,pose,'r' if facing>0 else 'l']

class Audio:
    def __init__(self): self.enabled=AUDIO['enabled']; self.started=False; self.events=[]
    def stop(self): self.started=False
    def toggle(self): self.enabled=not self.enabled

class BrowserGame(Game):
    def __init__(self):
        self.canvas=Canvas(); self.engine=Combat(); self.audio=Audio(); self.art=Art()
        self.selected=ROSTER['default_player']; self.opponent=ROSTER['default_opponent']
        self.selection_slot=0; self.commands=CommandBuffer(); self.moves_resume='title'
        self.difficulty=MATCH['default_difficulty']; self.keys=set(); self.mouse=(-1,-1)
        self.renderer=Renderer(self.canvas,self.art,self); self.running=True
        self.resume_state='fight'; self.fullscreen_requested=False
    def fullscreen_toggle(self): self.fullscreen_requested=True
    def close(self): self.to_title()
    def key(self,key,down):
        event=types.SimpleNamespace(keysym=key)
        (self.key_down if down else self.key_up)(event)
    def pointer(self,x,y,clicked=False):
        self.mouse=(x,y)
        if clicked: self.click(types.SimpleNamespace(x=x,y=y))
    def blur(self):
        self.keys.clear(); self.commands.clear()
        if self.engine.state in ('fight','intro','finish_window','finisher','round_end','training_reset'):
            self.resume_state=self.engine.state; self.engine.state='paused'
    def select(self,player,opponent,difficulty):
        if self.engine.state not in ('title','options'): self.to_title()
        if player not in FIGHTERS or opponent not in FIGHTERS: raise ValueError('Unknown fighter')
        self.selected=player; self.opponent=opponent; self.difficulty=max(0,min(2,int(difficulty)))
    def action(self,name):
        if name in ('arcade','versus','training'): self.start(name)
        elif name=='menu': self.to_title()
        elif name=='moves': self.toggle_moves()
        elif name=='sound': self.audio.toggle()
        elif name=='pause':
            if self.engine.state=='paused': self.resume()
            elif self.engine.state not in ('title','options','moves','match_end'): self.blur()
        elif name=='restart': self.start(self.engine.mode)
    def tick(self,dt):
        self.engine.opponent_keys=self.held('player_two')
        self.engine.update(dt,self.held('player_one'))
        self.renderer.render(dt)
        e=self.engine
        return json.dumps({'commands':[self.canvas.background]+self.canvas.commands,
            'sounds':e.pop_events(),'sound':self.audio.enabled,'music':self.audio.started and e.state not in ('paused','title','moves'),
            'state':e.state,'mode':e.mode,'round':e.round,'timer':e.timer,
            'selected':self.selected,'opponent':self.opponent,'difficulty':self.difficulty,
            'fighters':[{'name':f.name,'hp':round(f.hp),'meter':round(f.meter),'wins':f.wins,'x':round(f.x),'action':f.action} for f in e.fighters],
            'buttons':[{'x':x,'y':y,'w':w,'h':h} for x,y,w,h,fn in self.renderer.buttons]},separators=(',',':'))

